<?php $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$canManage=\App\Core\Authorization::allows('units.manage'); ?>
<div class="section-heading"><div><div class="eyebrow">Operação</div><h1>Unidades</h1><p class="text-secondary mb-0"><?=$canMultiunit?'Cadastre filiais, edite endereços e vincule profissionais.':'Edite os dados e o endereço da unidade principal.'?></p></div><span class="badge text-bg-light">Limite do plano: <?=(int)$limit?></span></div>
<?php if($canManage&&$canMultiunit):?><div class="card mb-4"><div class="card-header"><strong>Cadastrar nova unidade</strong></div><div class="card-body"><form class="row g-3" method="post" action="/units"><?php echo \App\Core\CSRF::field();?><div class="col-md-3"><label class="form-label">Nome da unidade</label><input class="form-control" name="name" placeholder="Ex.: Unidade Centro" required></div><div class="col-md-5"><label class="form-label">Endereço inicial</label><input class="form-control" name="address" placeholder="Você completará CEP, número e localização na próxima tela"></div><div class="col-md-2"><label class="form-label">Telefone</label><input class="form-control" name="phone" placeholder="(00) 0000-0000"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Cadastrar unidade</button></div></form></div></div><?php elseif($canManage):?><div class="alert alert-info d-flex flex-wrap justify-content-between align-items-center gap-2"><span>Seu plano possui uma unidade. Você pode editar todos os dados públicos, endereço, mapa, contatos e comodidades.</span><a class="btn btn-primary" href="/settings/unit">Editar unidade principal</a></div><?php endif;?>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Unidade</th><th>Endereço</th><th>Profissionais</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($units as $unit):$address=implode(', ',array_filter([$unit['address']??null,$unit['address_number']??null,$unit['district']??null,$unit['city']??null,$unit['state']??null]));?><tr><td><strong><?=$e($unit['name'])?></strong><?php if($unit['is_primary']):?><span class="badge text-bg-primary ms-1">Principal</span><?php endif;?></td><td><?=$e($address?:'Endereço ainda não preenchido')?></td><td><?=(int)$unit['professionals_count']?></td><td><?=$unit['active']?'<span class="badge text-bg-success">Ativa</span>':'<span class="badge text-bg-secondary">Inativa</span>'?></td><td class="text-end"><?php if($canManage):?><a class="btn btn-sm btn-outline-primary" href="<?=(!$canMultiunit&&(int)$unit['is_primary']===1)?'/settings/unit':'/units/'.(int)$unit['id'].'/edit'?>">Editar unidade</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$units):?><tr><td colspan="5"><div class="empty-state">Nenhuma unidade encontrada. Use “Editar unidade principal” para iniciar o cadastro.</div></td></tr><?php endif;?></tbody></table></div></div>
